reversal.fixed_text:
let (major, text) = numeric_identifier(text, pos)?;
let mut has_wildcard = false;

let (minor, text) = if let Some(text) = text.strip_prefix('.') {
    pos = Position::Minor;
    if let Some(text) = text.strip_prefix('*') {
        has_wildcard = true;
        if default_op {
            op = Op::Wildcard;
        }
        (None, text)
    } else {
        let (minor, text) = numeric_identifier(text, pos)?;
        (Some(minor), text)
    }
} else {
    (None, text)
};

let (patch, text) = if let Some(text) = text.strip_prefix('.') {
    pos = Position::Patch;
    if let Some(text) = text.strip_prefix('*') {
        if default_op {
            op = Op::Wildcard;
        }
        (None, text)
    } else if has_wildcard {
        return Err(Error::new(ErrorKind::UnexpectedAfterWildcard));
    } else {
        let (patch, text) = numeric_identifier(text, pos)?;
        (Some(patch), text)
    }
} else {
    (None, text)
};

reversal.parent_text:
let (major, text) = numeric_identifier(text, pos)?;

let (minor, text) = if let Some(text) = text.strip_prefix('.') {
    pos = Position::Minor;
    if let Some(text) = text.strip_prefix('*') {
        if default_op {
            op = Op::Wildcard;
        }
        (None, text)
    } else {
        let (minor, text) = numeric_identifier(text, pos)?;
        (Some(minor), text)
    }
} else {
    (None, text)
};

let (patch, text) = if let Some(text) = text.strip_prefix('.') {
    pos = Position::Patch;
    if let Some(text) = text.strip_prefix('*') {
        if default_op {
            op = Op::Wildcard;
        }
        (None, text)
    } else if op == Op::Wildcard {
        return Err(Error::new(ErrorKind::UnexpectedAfterWildcard));
    } else {
        let (patch, text) = numeric_identifier(text, pos)?;
        (Some(patch), text)
    }
} else {
    (None, text)
};
